  x.onload=function(){if(x.status>=200&&x.status<300){try{res(JSON.parse(x.responseText));}catch(e){rej(new Error('رد غير صالح'));}}else {mapError(new URL(url,location.href).hostname,'HTTP '+x.status);rej(new Error('HTTP '+x.status));}};
