  var v={};(j.properties.layers||[]).forEach(function(l){var d=(l.unit_measure&&l.unit_measure.d_factor)||10,m=l.depths&&l.depths[0]&&l.depths[0].values&&l.depths[0].values.mean;if(m!=null)v[l.name]=m/d;});
