function callApi(c,name){if(!CONFIG.API_BASE)return Promise.resolve(null);return tfetch(CONFIG.API_BASE+'/analyze?street='+encodeURIComponent(name)+'&lat='+c.lat+'&lng='+c.lng,12000).catch(function(){return null;});}
