/* ================= التوصيات من بيانات الشارع (بدل القيم الثابتة) ================= */
var TREES_ORIG=JSON.parse(JSON.stringify(TREES)),TW_REC={key:null};
var USEAR={roads:'طرق',parking:'مواقف',squares:'ساحات',home:'منازل',urban_open_green_space:'حدائق',natural_areas:'مناطق طبيعية'};
var CROWNAR={small:'صغير (أقل من 5م)',medium:'متوسط (5–10م)',large:'كبير (أكثر من 10م)'};
function twStreetStats(){
 var st=twStreet();if(!st)return null;
 var tr=twTrees('B');if(!tr)return null;
 var agg={},awc=0,cf=0,fb=0,nd=0,maxd=0,cells={};
 tr.forEach(function(t){if(!t.pk)return;var id=t.pk.t[0],a=agg[id]||(agg[id]={t:t.pk.t,n:0,sum:0,f:{},ctx:{}});a.n++;
  var mine=t.rec.list.filter(function(o){return o.t[0]===id;})[0];a.sum+=mine.score;mine.f.forEach(function(x){a.f[x[0]]=(a.f[x[0]]||0)+x[1];});a.ctx[t.rec.ctx]=1;});
 st.pts.forEach(function(p){var x=soilX(p.ci);awc+=x.awc;cf+=x.cf;nd++;if(p.dist){fb++;maxd=Math.max(maxd,p.dist);}cells[p.ci]=1;});
 var list=Object.keys(agg).map(function(k){var a=agg[k];return {t:a.t,n:a.n,score:Math.round(a.sum/a.n),f:Object.keys(a.f).map(function(x){return [x,Math.round(a.f[x]/a.n)];}),ctx:Object.keys(a.ctx)};})
  .sort(function(a,b){return b.n-a.n||b.score-a.score;});
 return {st:st,tr:tr,list:list,awc:Math.round(awc/nd),cf:Math.round(cf/nd*10)/10,fb:fb,nd:nd,maxd:maxd,cells:Object.keys(cells).length,planted:tr.n,blocked:tr.bl||0,ex:tr.ex||0};
}
function twApplyTrees(){
 var k=S.sel&&S.sel.name;if(TW_REC.key===k)return;TW_REC.key=k;
 var s=twStreetStats();TW_REC.stats=s;
 var slots=['ghaf','sidr','samar'];
 slots.forEach(function(sl,i){
  var o=s&&s.list[i];if(s&&!o){var cands=twCandidates().filter(function(c){return !s.list.some(function(x){return x.t[0]===c.t[0];});});var cc=cands[i-s.list.length];if(cc)o={t:cc.t,n:0,score:cc.score,f:cc.f,ctx:cc.ctx};}
  if(!o){TREES[sl]=JSON.parse(JSON.stringify(TREES_ORIG[sl]));TREES[sl].fromDb=false;return;}
  var t=o.t,ctxAr=o.ctx.map(function(c){return HWAR[c];}).join('، ');
  var uses=(t[7]||'').split(';').map(function(u){return USEAR[u]||u;}).join(' · ');
  var tieN=0;s.tr.forEach(function(x){if(x.pk&&x.pk.t[0]===t[0])tieN=Math.max(tieN,x.rec.ties.length);});
  var why=(o.n===0?'بديل مناسب لهذا الشارع (درجة '+o.score+')، غير مستخدم حاليًا ويمكن اختياره من لوحة الأشجار في المحاكاة':'مقترحة في '+o.n+' موقع من '+s.planted+' على هذا الشارع ('+ctxAr+')'+(tieN>1?'، وتعادلت مع '+(tieN-1)+' أشجار أخرى فاختيرت حسب الدليل (مستدامة ← ظل أعلى ← ماء أقل)':''))+'. احتياجها للماء '+WAR[t[3]]+'، والتربة تحت الشارع تحتفظ بمتوسط '+s.awc+' مم ماء فقط حتى عمق متر، وحجمها '+SIZEAR[t[4]]+' يناسب نوع الشارع'+(t[6]==='tolerant'?'، وتتحمّل الملوحة حسب الدليل':'')+'.';
  var tags=[];if(t[3]==='low')tags.push('مياه أقل');tags.push('حجم '+SIZEAR[t[4]]);if(t[6]==='tolerant')tags.push('تتحمّل الملوحة');if(t[5]==3)tags.push('ظل كثيف');if(t[8]==='True')tags.push('مستدامة حسب الدليل');
  var notes=[];if(s.cf>15)notes.push('الحصى في التربة '+s.cf+'%: يلزم تجهيز الحفرة واستبدال جزء من التربة.');
  if(s.fb)notes.push(s.fb+' من '+s.nd+' نقطة قيم تربتها من أقرب مربع SoilGrids (حتى '+s.maxd+' م) لأن مربعها عمراني مستبعد.');
  var db=null;(window.TREEDB||[]).forEach(function(x){if(x.id===t[0])db=x;});
  TREES[sl]={tid:t[0],ar:t[1],en:t[0]+' · دليل الرياض',lat:t[2],score:o.score,crit:o.f,fromDb:true,count:o.n,
   traits:[['احتياج الماء',WAR[t[3]]],['حجم التاج',CROWNAR[t[4]]],['تحمّل الملوحة',SALAR[t[6]]||'غير مذكور في الدليل'],['الظل',['','منخفض','متوسط','عالٍ'][t[5]]],['الاستخدام في الدليل',uses],['عدد المواقع',o.n+' من '+s.planted]],
   why:why,tags:tags,note:notes.join(' ')};
 });
}
