/* ================= الشعار + التنقل + تغيير الشجرة + التكلفة والمياه ================= */
LOGO='<button class="logo wf-logo" data-go="home" aria-label="وريف — الرئيسية"><img src="'+(document.getElementById('wareef-logo-data')||{}).textContent+'" alt="وريف"></button>';
