document.addEventListener('click',function(e){var el=e.target.closest('[data-act="restart"]');if(!el)return;e.stopImmediatePropagation();
 S.sel=null;S.q='';S.view='after';S.scen='B';S.years=5;TW.key=null;TW.trees=null;TW.ovr={};TW_REC.key=null;if(MAP.map&&MAP.map.closePopup)MAP.map.closePopup();location.hash='home';render();},true);

/* ---- تغيير نوع الشجرة: المستخدم يختار، أو يطلب من النظام بديلًا ---- */
TW.ovr={};
function twKey(t){return t.i+':'+t.side;}
var _twTreesBase=twTrees;
twTrees=function(scen){var tr=_twTreesBase(scen);if(!tr||tr.ovrApplied)return tr;
 tr.forEach(function(t){var o=TW.ovr[twKey(t)];if(o&&t.pk&&!t.blocked){var m=t.rec.list.filter(function(x){return x.t[0]===o;})[0];if(m){t.pk=m;t.user=true;}}});
 var cnt={};tr.forEach(function(t){if(t.pk&&!t.blocked)cnt[t.pk.t[0]]=(cnt[t.pk.t[0]]||0)+1;});
 tr.counts=Object.keys(cnt).map(function(k){return [k,cnt[k]];}).sort(function(a,b){return b[1]-a[1];});tr.ovrApplied=true;return tr;};
function twChange(key,id,all){
 var tr=TW.trees;if(!tr)return;var t0=tr.filter(function(t){return twKey(t)===key;})[0];if(!t0)return;
 if(all){var from=t0.pk.t[0];tr.forEach(function(t){if(t.pk&&!t.blocked&&t.pk.t[0]===from&&t.rec.list.some(function(x){return x.t[0]===id;}))TW.ovr[twKey(t)]=id;});}
 else TW.ovr[key]=id;
 TW.trees=null;TW_REC.key=null;twSyncCounts();if(MAP.map)MAP.map.closePopup();render();
}
function twAlt(key){var tr=TW.trees,t0=tr&&tr.filter(function(t){return twKey(t)===key;})[0];if(!t0)return;
 var used={};tr.forEach(function(t){if(t.pk)used[t.pk.t[0]]=1;});
 var cand=t0.rec.list.filter(function(x){return x.t[0]!==t0.pk.t[0];});
 var fresh=cand.filter(function(x){return !used[x.t[0]];})[0]||cand[0];if(fresh)twChange(key,fresh.t[0],false);}
function twChooser(t){if(!t.pk||t.blocked)return '';var k=twKey(t);
 return '<div class="tw-chg"><b>تغيير الشجرة</b><select data-twsel="'+k+'">'+t.rec.list.map(function(x){return '<option value="'+x.t[0]+'"'+(x.t[0]===t.pk.t[0]?' selected':'')+'>'+x.t[1]+' — '+x.score+'</option>';}).join('')+'</select>'+
  '<label><input type="checkbox" data-twall="'+k+'"> طبّق على كل أشجار هذا النوع في الشارع</label>'+
  '<button class="btn sec" data-twalt="'+k+'">اقترح شجرة مختلفة</button>'+(t.user?'<small>تم التغيير يدويًا</small>':'')+'</div>';}
var _twPopup=twPopup;twPopup=function(t){return _twPopup(t).replace(/<\/div>$/,'')+twWaterHTML(t)+twChooser(t)+'</div>';};
document.addEventListener('change',function(e){var s=e.target;if(!s.matches||!s.matches('select[data-twsel]'))return;var k=s.getAttribute('data-twsel'),all=document.querySelector('input[data-twall="'+k+'"]');twChange(k,s.value,all&&all.checked);});
