/* ---- المياه والتكلفة ----
   الري اليومي من دليل التشجير (ص 12–13): الشتلة 25–30 لتر، الناضجة 50–60 لتر. نأخذ داخل النطاق حسب فئة احتياج الشجرة.
   سعر المياه افتراضي قابل للتعديل (ر.س/م³). أسعار الزراعة والري والصيانة تقديرية من وريف الأصلية. */
CONFIG.WATER_PRICE=CONFIG.WATER_PRICE||6;
var WLPD={young:{low:25,medium:27.5,high:30},mature:{low:50,medium:55,high:60}};
function twTreeWater(sp,years){var st=years===0?'young':'mature',l=WLPD[st][sp[3]]||55,m3=l*365/1000;return {l:l,m3:m3,cost:m3*CONFIG.WATER_PRICE};}
function twWater(scen,years){var tr=twTrees(scen),y=years==null?S.years:years,o={l:0,m3:0,cost:0,n:0};if(!tr)return null;
 tr.forEach(function(t){if(!t.pk||t.blocked)return;var w=twTreeWater(t.pk.t,y);o.l+=w.l;o.m3+=w.m3;o.cost+=w.cost;o.n++;});o.m3=Math.round(o.m3);o.cost=Math.round(o.cost);return o;}
function twWaterHTML(t){if(!t.pk||t.blocked)return '';var y=twTreeWater(t.pk.t,0),m=twTreeWater(t.pk.t,10);
 return '<div class="tw-wat"><b>المياه والتكلفة لهذه الشجرة</b><span>شتلة: '+y.l+' لتر/يوم · ناضجة: '+m.l+' لتر/يوم ('+m.m3.toFixed(1)+' م³/سنة)</span><span>تكلفة المياه السنوية: '+Math.round(y.cost)+' ر.س (شتلة) · '+Math.round(m.cost)+' ر.س (ناضجة) بسعر '+CONFIG.WATER_PRICE+' ر.س/م³</span><span>زراعة 850 · شبكة ري 230 · صيانة 140 ر.س/سنة (تقديري)</span></div>';}
function twCostAll(scen){var c=cost(scen),w=twWater(scen,5),w0=twWater(scen,0),n=SC[scen].trees;
 /* 5 سنوات: سنتان شتلة + ثلاث سنوات ناضجة */
 var water5=w&&w0?Math.round(w0.cost*2+w.cost*3):0;
 return {plant:c.plant,irr:c.irr,maint5:c.maint*5,water5:water5,waterYr:w?w.cost:0,total:c.plant+c.irr+c.maint*5+water5,n:n};}
total5=function(s){return twStreet()?twCostAll(s).total:(function(){var c=cost(s);return c.plant+c.irr+c.maint*5;})();};

/* ---- لوحة اختيار شجرة الشارع (يسار المحاكاة) ---- */
TW.choice=null;
function twCandidates(){var tr=_twTreesBase('B');if(!tr)return [];var agg={};
 tr.forEach(function(t){if(t.blocked||!t.rec||t.rec.excluded)return;t.rec.list.forEach(function(o){var a=agg[o.t[0]]||(agg[o.t[0]]={t:o.t,sum:0,n:0,f:{},ctx:{}});a.sum+=o.score;a.n++;o.f.forEach(function(x){a.f[x[0]]=(a.f[x[0]]||0)+x[1];});a.ctx[t.rec.ctx]=1;});});
 var sites=tr.filter(function(t){return !t.blocked&&t.rec&&!t.rec.excluded;}).length;
 return Object.keys(agg).map(function(k){var a=agg[k];return {t:a.t,score:Math.round(a.sum/a.n),cover:sites?a.n/sites:0,f:Object.keys(a.f).map(function(x){return [x,Math.round(a.f[x]/a.n)];}),ctx:Object.keys(a.ctx)};})
  .filter(function(c){return c.cover>=0.5;}).sort(twRank);}
var _twTreesChoice=twTrees;
twTrees=function(scen){var tr=_twTreesChoice(scen);if(!tr||tr.choiceApplied||!TW.choice)return tr;
 tr.forEach(function(t){if(!t.pk||t.blocked||TW.ovr[twKey(t)])return;var m=t.rec.list.filter(function(x){return x.t[0]===TW.choice;})[0];if(m){t.pk=m;t.user=true;}});
 var cnt={};tr.forEach(function(t){if(t.pk&&!t.blocked)cnt[t.pk.t[0]]=(cnt[t.pk.t[0]]||0)+1;});
 tr.counts=Object.keys(cnt).map(function(k){return [k,cnt[k]];}).sort(function(a,b){return b[1]-a[1];});tr.choiceApplied=true;return tr;};
function twPickerHTML(){var c=twCandidates();if(!c.length)return '';var auto=c[0].t[0],curId=TW.choice||auto;
 return '<div class="tw-pick"><div class="tw-pick-h"><b>اختر شجرة الشارع</b><small>تُطبَّق على المحاكاة والتكلفة والمياه</small></div>'+
  c.slice(0,12).map(function(o,i){var t=o.t,img=window.TIMG&&TIMG[t[0]],on=t[0]===curId;
   return '<button class="tw-pi'+(on?' on':'')+'" data-act="twpick:'+t[0]+'">'+(img?'<img src="'+img+'" alt="">':'<span class="ph"></span>')+'<span class="tx"><b>'+t[1]+(t[0]===auto?' <em>الأنسب</em>':'')+'</b><small>'+o.score+' · ماء '+WAR[t[3]]+' · '+SIZEAR[t[4]]+' · '+twTreeCost(t,0).plant+' ر.س'+(twSeedPrice(t).real?'':'*')+'</small></span></button>';}).join('')+
  (TW.choice||Object.keys(TW.ovr).length?'<button class="tw-reset" data-act="twpick:auto">رجوع للاختيار التلقائي</button>':'')+'</div>';}
document.addEventListener('click',function(e){var el=e.target.closest('[data-act^="twpick:"]');if(!el)return;e.stopImmediatePropagation();
 var id=el.getAttribute('data-act').split(':')[1];TW.choice=id==='auto'?null:id;TW.ovr={};TW.trees=null;TW_REC.key=null;twSyncCounts();if(MAP.map)MAP.map.closePopup();var g=el.getAttribute('data-go');if(g)go(g);else render();},true);
function twMonSp(i){if(!twStreet())return null;var tr=twTrees(S.scen);if(!tr)return null;var pl=tr.filter(function(t){return t.pk&&!t.blocked;});return pl[i]?pl[i].pk.t[1]:null;}

/* ---- مؤشرات السيناريو محسوبة من الأشجار الفعلية (بدل القيم الثابتة) ----
   الظل = مساحة تيجان الأشجار ÷ مساحة ممر الشارع (طول الشارع × عرض حتى خط الأشجار + 3م)، التداخل لا يُحسب مرتين.
   المياه/الاستدامة = من فئة احتياج الماء في الدليل (منخفض 100، متوسط 75، مرتفع 50).
   رصيف مظلل = مجموع أقطار التيجان على امتداد الشارع (لا يتجاوز التباعد). */
var _origSCv={};['A','B','C'].forEach(function(k){_origSCv[k]={shade:SC[k].shade,water:SC[k].water,ws:SC[k].ws,ben:SC[k].ben};});
function twMetrics(k){var tr=twTrees(k),st=TW.st;if(!tr||!st)return null;var sp=10*(SPACE[k]||2),offs=[],area={0:0,5:0,10:0},shadeLen=0,wr=0,n=0;
 tr.forEach(function(t){if(!t.pk||t.blocked)return;n++;if(t.off)offs.push(t.off);wr+=WRANK[t.pk.t[3]];
  [0,5,10].forEach(function(y){var R=twCrown(t.pk.t)*(y===0?0.30:(y===5?0.64:1));area[y]+=Math.min(Math.PI*R*R,2*R*sp);});
  shadeLen+=Math.min(2*twCrown(t.pk.t)*0.64,sp);});
 if(!n)return {shade:{0:0,5:0,10:0},water:'—',ws:0,ben:0,n:0};
 var off=offs.length?offs.reduce(function(a,b){return a+b;},0)/offs.length:6,corr=st.len*2*(off+3),avg=wr/n;
 var sh={};[0,5,10].forEach(function(y){sh[y]=Math.min(100,Math.round(area[y]/corr*100));});
 return {shade:sh,water:avg<0.5?'منخفض':(avg<1.5?'متوسط':'مرتفع'),ws:Math.round(100-25*avg),ben:Math.round(shadeLen),n:n};}
var _twSync0=twSyncCounts;
twSyncCounts=function(){_twSync0();var ok=twStreet();['A','B','C'].forEach(function(k){var m=ok?twMetrics(k):null;
 if(m){SC[k].shade=m.shade;SC[k].water=m.water;SC[k].ws=m.ws;SC[k].ben=m.ben;}else{SC[k].shade=_origSCv[k].shade;SC[k].water=_origSCv[k].water;SC[k].ws=_origSCv[k].ws;SC[k].ben=_origSCv[k].ben;}});TW.trees=null;};

/* ---- تكلفة ومياه واستدامة حسب نوع كل شجرة ----
   المياه (لتر/يوم): الشتلة 25–30 (دليل الرياض ص12–13). الناضجة حسب الحجم: صغيرة 25 (50 لتر يوم بعد يوم)، متوسطة 55، كبيرة 75
   (دراسة معدلات ري المسطحات في الرياض، ScienceDirect)، ثم × فئة احتياج الماء في الدليل: منخفض 0.8، متوسط 1.0، مرتفع 1.2.
   الزراعة = سعر الشتلة (مشاتل سعودية: صغيرة 30، متوسطة 65، كبيرة 150 ر.س) + حجم الحفرة من قواعد الدليل
   (صغيرة 1.2×1.2×1.2م، متوسطة/كبيرة 2×2×2م) × 90 ر.س/م³ حفر وتربة زراعية (افتراض) + 60 ر.س تثبيت وعمالة (افتراض).
   +25% على الحفرة إذا الحصى في التربة >15% (استبدال تربة).
   الاستدامة المائية للنوع = ظل التاج الناضج لكل لتر ماء، منسوبة لأفضل نوع في الكتالوج (0–100). */
var PRICE={seed:{small:30,medium:65,large:150},pit:{small:1.728,medium:8,large:8},soil:90,labor:60,irr:{small:180,medium:230,large:280},maint:{small:100,medium:140,large:180}};
var WMAT={small:25,medium:55,large:75},WYNG={low:25,medium:27.5,high:30},WK={low:0.8,medium:1,high:1.2};
twTreeWater=function(sp,years){var l=years===0?WYNG[sp[3]]||27.5:Math.round((WMAT[sp[4]]||55)*(WK[sp[3]]||1)),m3=l*365/1000;return {l:l,m3:m3,cost:m3*CONFIG.WATER_PRICE};};
function twTreeCost(sp,cf){var z=sp[4]||'medium',pit=PRICE.pit[z]*PRICE.soil*(cf>15?1.25:1);return {plant:Math.round(PRICE.seed[z]+pit+PRICE.labor),irr:PRICE.irr[z],maint:PRICE.maint[z]};}
var WSEFF=null;function twSpeciesWS(sp){if(!WSEFF){WSEFF={};var mx=0;WD.trees.forEach(function(t){var R=twCrown(t),e=Math.PI*R*R/twTreeWater(t,10).l;WSEFF[t[0]]=e;mx=Math.max(mx,e);});for(var k in WSEFF)WSEFF[k]=Math.round(WSEFF[k]/mx*100);}return WSEFF[sp[0]]||0;}
var _costOrig=cost;
cost=function(s){if(!twStreet())return _costOrig(s);var tr=twTrees(s),o={plant:0,irr:0,maint:0};if(!tr)return _costOrig(s);
 tr.forEach(function(t){if(!t.pk||t.blocked)return;var c=twTreeCost(t.pk.t,soilX(t.p.ci).cf);o.plant+=c.plant;o.irr+=c.irr;o.maint+=c.maint;});return o;};
var _twMetrics0=twMetrics;
twMetrics=function(k){var m=_twMetrics0(k);if(!m||!m.n)return m;var tr=twTrees(k),s=0,n=0;tr.forEach(function(t){if(!t.pk||t.blocked)return;s+=twSpeciesWS(t.pk.t);n++;});m.ws=Math.round(s/n);return m;};
twWaterHTML=function(t){if(!t.pk||t.blocked)return '';var y=twTreeWater(t.pk.t,0),m=twTreeWater(t.pk.t,10),c=twTreeCost(t.pk.t,soilX(t.p.ci).cf);
 return '<div class="tw-wat"><b>المياه والتكلفة لهذه الشجرة</b><span>شتلة: '+y.l+' لتر/يوم · ناضجة: '+m.l+' لتر/يوم ('+m.m3.toFixed(1)+' م³/سنة)</span><span>مياه سنوية: '+Math.round(y.cost)+' ر.س (شتلة) · '+Math.round(m.cost)+' ر.س (ناضجة)</span><span>زراعة '+c.plant+' · شبكة ري '+c.irr+' · صيانة '+c.maint+' ر.س/سنة</span><span>استدامة مائية للنوع: '+twSpeciesWS(t.pk.t)+'/100 (ظل لكل لتر)</span></div>';};

/* ---- أسعار فعلية لكل نوع (أعلى سعر منشور = الحجم الأكبر)، مشاتل سعودية، 2026-11 ----
   mshtly.com و plantshome.sa. "تقريب الجنس" = سعر نوع قريب من نفس الجنس. الأنواع غير المنشورة: تقدير حسب الحجم. */
var SPPRICE={
 T042:[69.6,'مشتلي — Prosopis'],T049:[72.5,'مشتلي — سدر'],T016:[94.25,'مشتلي — نيم'],T033:[113.1,'مشتلي — زنزلخت'],
 T015:[150.8,'مشتلي — لبخ'],T026:[145,'مشتلي — بونسيانا'],T029:[243.6,'مشتلي — لسان العصفور'],
 T027:[145,'مشتلي — فيكس نيتيدا (تقريب الجنس)'],T028:[145,'مشتلي — فيكس نيتيدا (تقريب الجنس)'],T030:[145,'مشتلي — فيكس نيتيدا (تقريب الجنس)'],
 T045:[179,'موطن النباتات — ترمناليا (تقريب الجنس)'],T046:[179,'موطن النباتات — ترمناليا منتالي']};
function twSeedPrice(sp){var p=SPPRICE[sp[0]];return p?{v:p[0],src:p[1],real:true}:{v:PRICE.seed[sp[4]||'medium'],src:'تقدير حسب الحجم (لا يوجد سعر منشور)',real:false};}
/* الأنواع المستدامة في الدليل تُخفَّض مياهها 10% (مؤشر تحمّل الجفاف في الدليل) */
twTreeWater=function(sp,years){var l=years===0?WYNG[sp[3]]||27.5:Math.round((WMAT[sp[4]]||55)*(WK[sp[3]]||1)*(sp[8]==='True'?0.9:1)),m3=l*365/1000;return {l:l,m3:m3,cost:m3*CONFIG.WATER_PRICE};};
WSEFF=null;
twTreeCost=function(sp,cf){var z=sp[4]||'medium',pit=PRICE.pit[z]*PRICE.soil*(cf>15?1.25:1),sd=twSeedPrice(sp);return {plant:Math.round(sd.v+pit+PRICE.labor),seed:sd,irr:PRICE.irr[z],maint:PRICE.maint[z]};};
